import raw from "./facts.json";

// facts.json is generated by scripts/deck-facts.mjs from the repo's results/ and deployments/.

export interface DeployedContract {
  name: string;
  address: string;
  tx: string | null;
  block: number | null;
}

export interface DeckFacts {
  tests: { suites: { name: string; count: number }[]; total: number; source: string };
  gas: {
    network: string | null;
    beefyCommitment: number | null;
    headerImport: number | null;
    setHandoff: number | null;
    storageProof: number | null;
  } | null;
  beefy: {
    network: string | null;
    at: string | null;
    fromSet: number | null;
    toSet: number | null;
    rotations: number | null;
    signers: string[];
    commitmentBlock: number | null;
    commitmentGas: number | null;
    header: number | null;
    headerGas: number | null;
    mmrRoot: string | null;
    stateRoot: string | null;
    trieId: string | null;
    storageProofBytes: number | null;
    storageProofGas: number | null;
  } | null;
  parlia: {
    network: string | null;
    at: string | null;
    validators: string[];
    turnLength: number | null;
    block: number | null;
    headers: number | null;
    bytes: number | null;
    distinctSealers: number | null;
    untrustedSealers: number;
    untrustedSeals: number | null;
    gas: number | null;
    finalizedHashMatches: boolean | null;
    receiptProofNodes: number | null;
    receiptProofBytes: number | null;
  } | null;
  attacks: { total: number; items: { id: string; reason: string | null; rejected: boolean }[] } | null;
  wasm: {
    wasmBytes: number | null;
    window48Headers: number | null;
    window48RefTimeMs: number | null;
    window48ProofSize: number | null;
    evmWindow48Gas: number | null;
  } | null;
  deployCost: { portaldotTpot: number | null; bscTbnb: number | null } | null;
  deployment: {
    portaldot: { updatedAt: string | null; contracts: DeployedContract[] } | null;
    bsc: { updatedAt: string | null; contracts: DeployedContract[] } | null;
  } | null;
  transfers: { label: string; chain: "portaldot" | "bsc"; tx: string; block: number | null }[];
  sources: string[];
}

export const facts: DeckFacts = raw as DeckFacts;

/** 77562 → "78k" */
export const kGas = (n: number | null | undefined) => (n == null ? "–" : `${Math.round(n / 1000)}k`);

/** 39303 → "39 KB" */
export const kb = (n: number | null | undefined) => (n == null ? "–" : `${Math.round(n / 1000)} KB`);
